/* Two-hand globe manipulation in XR reference space; no native SDK required. */
(()=>{
const T=AFRAME.THREE;
class GlobeGrabTransform{
 constructor(position,quaternion,scale,points,gain=1,depthAxis=null,depthGain=gain){this.position=position.clone();this.quaternion=quaternion.clone();this.scale=scale.clone();this.points=points.map(p=>p.clone());this.gain=gain;this.depthAxis=depthAxis?.clone().normalize();this.depthGain=depthGain;this.mid=this.midpoint(this.points);this.distance=this.points.length===2?Math.max(.08,this.points[0].distanceTo(this.points[1])):0;this.axis=this.points.length===2?this.points[1].clone().sub(this.points[0]).normalize():null}
 midpoint(points){return points.reduce((sum,p)=>sum.add(p),new T.Vector3()).multiplyScalar(1/points.length)}
 solve(points){const delta=this.midpoint(points).sub(this.mid),position=this.position.clone().addScaledVector(delta,this.gain);if(this.depthAxis)position.addScaledVector(this.depthAxis,delta.dot(this.depthAxis)*(this.depthGain-this.gain));const quaternion=this.quaternion.clone(),scale=this.scale.clone();if(points.length===2&&this.axis&&points[0].distanceTo(points[1])>.045){const axis=points[1].clone().sub(points[0]).normalize(),rotation=new T.Quaternion().setFromUnitVectors(this.axis,axis);quaternion.premultiply(rotation).normalize();const desired=Math.max(.45,Math.min(2.2,this.scale.x*points[0].distanceTo(points[1])/this.distance));scale.multiplyScalar(desired/this.scale.x)}return {position,quaternion,scale}}
}
window.GlobeGrabTransform=GlobeGrabTransform;
AFRAME.registerComponent('bimanual-globe',{
 init(){this.grabs=new Map();this.listeners=[];this.placed=false;this.highlight=new T.Mesh(new T.SphereGeometry(1.26,32,20),new T.MeshBasicMaterial({color:'#d8edff',transparent:true,opacity:.09,side:T.BackSide,depthWrite:false}));this.highlight.visible=false;this.el.object3D.add(this.highlight);this.ready=()=>this.bindInputs();this.el.sceneEl.addEventListener('loaded',this.ready);this.bindInputs();this.listen(this.el.sceneEl,'renderstart',()=>this.desktopResize());this.desktopResize();this.listen(document.getElementById('rig'),'child-attached',()=>this.bindInputs());this.listen(window,'blur',()=>this.releaseAll());this.listen(document,'visibilitychange',()=>{if(document.hidden)this.releaseAll()});this.listen(this.el.sceneEl,'exit-vr',()=>this.releaseAll());this.listen(this.el,'click',e=>{if(performance.now()<(this.suppressUntil||0)){e.stopPropagation();e.stopImmediatePropagation()}},true)},
 listen(el,event,fn,capture=false){if(!el)return;el.addEventListener(event,fn,capture);this.listeners.push(()=>el.removeEventListener(event,fn,capture))},
 bindInputs(){this.bound ||=new Set();for(const side of ['left','right']){const hand=document.getElementById(side==='left'?'globiquestLeftTrackedHand':'globiquestRightTrackedHand');if(hand&&!this.bound.has(hand)){this.bound.add(hand);this.listen(hand,'pinchstarted',e=>{const point=this.handPoint(hand,e.detail.position);if(this.start(hand,'pinch',point))e.stopImmediatePropagation()},true);this.listen(hand,'pinchmoved',e=>{const patch=window.globiquest.globePatch;if(patch?.source===hand){patch.move(hand,this.handPoint(hand,e.detail.position));e.stopImmediatePropagation();return}const grab=this.grabs.get(hand);if(grab){grab.point.copy(this.handPoint(hand,e.detail.position));grab.last=performance.now();this.suppressUntil=performance.now()+450;e.stopImmediatePropagation()}},true);this.listen(hand,'pinchended',e=>{if(window.globiquest.globePatch?.source===hand){window.globiquest.globePatch.end(hand);e.stopImmediatePropagation();return}if(this.grabs.has(hand)){this.end(hand);e.stopImmediatePropagation()}},true)}const controller=document.getElementById(side==='left'?'leftHand':'rightHand');if(controller&&!this.bound.has(controller)){this.bound.add(controller);this.listen(controller,'triggerdown',e=>{const patch=window.globiquest.globePatch;if(patch?.enabled&&this.start(controller,'controller',controller.object3D.getWorldPosition(new T.Vector3())))e.stopImmediatePropagation()},true);this.listen(controller,'triggerup',e=>{if(window.globiquest.globePatch?.source===controller){window.globiquest.globePatch.end(controller);e.stopImmediatePropagation()}},true);this.listen(controller,'gripdown',e=>{if(this.start(controller,'controller',controller.object3D.getWorldPosition(new T.Vector3())))e.stopImmediatePropagation()},true);this.listen(controller,'gripup',e=>{if(window.globiquest.globePatch?.source===controller){window.globiquest.globePatch.end(controller);e.stopImmediatePropagation();return}if(this.grabs.has(controller)){this.end(controller);e.stopImmediatePropagation()}},true);this.listen(controller,'controllerdisconnected',()=>{window.globiquest.globePatch?.end(controller);this.end(controller)})}}},
 handPoint(hand,point){return hand.object3D.parent.localToWorld(new T.Vector3(point.x,point.y,point.z))},
 pick(source,kind,point){if(window.globiquest?.travelEditing||window.globiquest.handUIIsTarget?.(source,kind==='pinch'?source.object3D.parent.worldToLocal(point.clone()):null)||window.globiquest.handInputReserved?.(source,kind==='pinch'?source.object3D.parent.worldToLocal(point.clone()):null))return false;const other=[...this.grabs.values()][0];if(other){const center=this.el.object3D.getWorldPosition(new T.Vector3()),radius=1.24*this.el.object3D.getWorldScale(new T.Vector3()).x;return other.kind===kind&&point.distanceTo(other.point)>.08&&(point.distanceTo(other.point)<1.25||point.distanceTo(center)<radius+.18)}const previous=document.getElementById('earthRoot')?.components['globe-rotation'];if(previous?.armed||previous?.moving||window.globiquest?.lensHeld||window.globiquest?.workspace==='lens')return false;const center=this.el.object3D.getWorldPosition(new T.Vector3()),radius=1.24*this.el.object3D.getWorldScale(new T.Vector3()).x;if(point.distanceTo(center)<radius+.18)return true;let ray;if(kind==='controller')ray=previous?.controllerRay(source);else{const origin=this.el.sceneEl.camera.getWorldPosition(new T.Vector3());ray=window.globiquest.handRay?.(source,source.object3D.parent.worldToLocal(point.clone()))||new T.Ray(origin,point.clone().sub(origin).normalize())}if(!ray)return false;const hit=ray.intersectSphere(new T.Sphere(center,radius),new T.Vector3());if(!hit)return false;const scope=previous?.movable(ray.origin,ray.direction);return !scope||scope.distance>ray.origin.distanceTo(hit)},
 start(source,kind,point){if(window.globiquest.workspace==='music')return false;if(window.globiquest.parachutes?.open||!this.el.object3D.visible)return false;const patch=window.globiquest.globePatch;if(patch?.enabled&&window.globiquest.workspace!=='explore'){if(patch.source&&patch.source!==source)return !!patch.pick(source,kind,point);if(!this.grabs.size)return patch.start(source,kind,point)}if(!this.moveEnabled)return false;if(this.grabs.has(source)||this.grabs.size>=2||!this.el.object3D.visible||!this.pick(source,kind,point))return false;const previous=document.getElementById('earthRoot')?.components['globe-rotation'];previous?.release();this.grabs.set(source,{source,kind,point:point.clone(),last:performance.now(),rotation:source.object3D.getWorldQuaternion(new T.Quaternion())});if(!this.placed)this.home={position:this.el.object3D.position.clone(),scale:this.el.object3D.scale.clone()};this.placed=true;this.highlight.visible=true;this.rebase();this.suppressUntil=performance.now()+450;if(this.resetButton)this.resetButton.style.display='';if(typeof notify==='function')notify(this.rotateOnly||window.globiquest.workspace==='explore'?'Rotate globe · sweep your pinched hand, or turn your controller.':this.grabs.size===2?'Two-hand globe hold · spread to resize, turn or move both hands.':'Globe held · move your hand; add a second pinch or grip to resize.');return true},
 rebase(){if(!this.grabs.size){this.frame=null;return}const object=this.el.object3D;object.updateWorldMatrix(true,false);const grabs=[...this.grabs.values()],points=grabs.map(g=>g.point),position=object.getWorldPosition(new T.Vector3()),quaternion=object.getWorldQuaternion(new T.Quaternion()),scale=object.getWorldScale(new T.Vector3());const camera=this.el.sceneEl.camera.getWorldPosition(new T.Vector3()),mid=points.reduce((s,p)=>s.add(p),new T.Vector3()).multiplyScalar(1/points.length);const near=mid.distanceTo(position)<1.24*scale.x+.3,gain=near?1:Math.min(4,Math.max(1,position.distanceTo(camera)/Math.max(.3,mid.distanceTo(camera))));const depthAxis=mid.clone().sub(camera).normalize(),depthGain=near?1:Math.min(12,Math.max(gain,position.distanceTo(camera)/Math.max(.3,mid.distanceTo(camera))));this.frame=new GlobeGrabTransform(position,quaternion,scale,points,gain,depthAxis,depthGain);this.turnCameraInverse=this.el.sceneEl.camera.getWorldQuaternion(new T.Quaternion()).invert();this.turnCamera=this.turnCameraInverse.clone().invert();this.startRotation=grabs[0].source.object3D.getWorldQuaternion(new T.Quaternion()).invert()},
 end(source){if(!this.grabs.delete(source))return;this.highlight.visible=this.grabs.size>0;this.suppressUntil=performance.now()+450;this.rebase()},
 releaseAll(){this.grabs.clear();this.highlight.visible=false;this.frame=null},
 resizeTo(value){const object=this.el.object3D;if(!this.placed)this.home={position:object.position.clone(),scale:object.scale.clone()};this.releaseAll();window.globiquest.globePatch?.end();this.placed=true;object.scale.setScalar(T.MathUtils.clamp(value,.45,2.2));object.updateWorldMatrix(true,false);const camera=this.el.sceneEl.camera.getWorldPosition(new T.Vector3()),position=object.getWorldPosition(new T.Vector3()),offset=position.clone().sub(camera),minimum=1.18*object.getWorldScale(new T.Vector3()).x+.3;if(offset.length()<minimum){if(offset.lengthSq()<.0001)this.el.sceneEl.camera.getWorldDirection(offset);object.position.copy(object.parent.worldToLocal(camera.add(offset.normalize().multiplyScalar(minimum))))}window.globiquest.globeScalePercent=Math.round(object.scale.x*100);if(this.resetButton)this.resetButton.style.display='';return object.scale.x},
 mouseHit(event){const canvas=this.el.sceneEl.canvas,camera=window.globiquest.xrPointerCamera?.()||this.el.sceneEl.camera;if(!canvas||!camera)return false;const bounds=canvas.getBoundingClientRect(),caster=new T.Raycaster();caster.setFromCamera(new T.Vector2((event.clientX-bounds.left)/bounds.width*2-1,-(event.clientY-bounds.top)/bounds.height*2+1),camera);const center=this.el.object3D.getWorldPosition(new T.Vector3()),radius=1.24*this.el.object3D.getWorldScale(new T.Vector3()).x,hit=caster.ray.intersectSphere(new T.Sphere(center,radius),new T.Vector3());if(!hit)return false;const distance=hit.distanceTo(caster.ray.origin);for(const el of this.el.sceneEl.querySelectorAll?.('.interactive')||[]){if(el.closest?.('#mapRoot'))continue;let visible=true;for(let o=el.object3D;o;o=o.parent)if(!o.visible)visible=false;if(!visible)continue;const ui=caster.intersectObject(el.object3D,true)[0];if(ui&&ui.distance<distance)return false}return true},
 desktopResize(){const canvas=this.el.sceneEl.canvas;if(!canvas||this.resizeBound)return;this.resizeBound=true;this.listen(canvas,'wheel',e=>{if(!this.mouseHit(e))return;e.preventDefault();e.stopImmediatePropagation();this.resizeTo(this.el.object3D.scale.x*Math.exp(-T.MathUtils.clamp(e.deltaY,-160,160)*.002));this.suppressUntil=performance.now()+450},{capture:true,passive:false});this.listen(canvas,'pointerdown',e=>{if(e.button!==0||!e.shiftKey||!this.mouseHit(e))return;document.getElementById('earthRoot')?.components['globe-rotation']?.release();const camera=document.getElementById('camera');this.resizeMouse={id:e.pointerId,y:e.clientY,scale:this.el.object3D.scale.x,camera,look:camera?.getAttribute('look-controls')?.enabled!==false};camera?.setAttribute('look-controls','enabled',false);this.suppressUntil=performance.now()+450;e.preventDefault();e.stopImmediatePropagation()},true);this.listen(window,'pointermove',e=>{if(!this.resizeMouse||e.pointerId!==this.resizeMouse.id)return;this.resizeTo(this.resizeMouse.scale*Math.exp((this.resizeMouse.y-e.clientY)*.006));this.suppressUntil=performance.now()+450});for(const event of ['pointerup','pointercancel','blur'])this.listen(window,event,()=>this.endMouseResize())},
 endMouseResize(){if(this.resizeMouse){this.resizeMouse.camera?.setAttribute('look-controls','enabled',this.resizeMouse.look);this.resizeMouse=null;this.suppressUntil=performance.now()+450}},
 reset(){window.globiquest.globePatch?.reset();this.releaseAll();this.placed=false;this.el.object3D.quaternion.identity();if(this.home){this.el.object3D.position.copy(this.home.position);this.el.object3D.scale.copy(this.home.scale)}if(this.resetButton)this.resetButton.style.display='none';window.globiquest?.refreshWorkspace?.()},
 tick(time,delta){if(!this.el.object3D.visible){if(this.grabs.size)this.releaseAll();return}const now=performance.now();for(const [source,grab] of [...this.grabs]){if(grab.kind==='pinch'&&now-grab.last>450){this.end(source);continue}if(grab.kind==='controller')grab.point.copy(source.object3D.getWorldPosition(new T.Vector3()))}if(!this.frame||!this.grabs.size)return;const grabs=[...this.grabs.values()],result=this.frame.solve(grabs.map(g=>g.point));if(grabs.length===1&&grabs[0].kind==='controller'){const rotation=grabs[0].source.object3D.getWorldQuaternion(new T.Quaternion()).multiply(this.startRotation);result.quaternion.copy(rotation.multiply(this.frame.quaternion)).normalize()}if(this.rotateOnly||window.globiquest.workspace==='explore'){result.position.copy(this.frame.position);if(grabs.length===1&&grabs[0].kind==='pinch'){const delta=grabs[0].point.clone().sub(this.frame.points[0]).applyQuaternion(this.turnCameraInverse),turn=new T.Quaternion().setFromEuler(new T.Euler(-delta.y*4,delta.x*4,0,'YXZ'));turn.premultiply(this.turnCamera).multiply(this.turnCameraInverse);result.quaternion.copy(turn.multiply(this.frame.quaternion)).normalize()}}const camera=this.el.sceneEl.camera.getWorldPosition(new T.Vector3()),offset=result.position.clone().sub(camera),minDistance=1.18*result.scale.x+.3;if(offset.length()<minDistance){if(offset.lengthSq()<.0001)this.el.sceneEl.camera.getWorldDirection(offset);result.position.copy(camera).add(offset.normalize().multiplyScalar(minDistance))}result.position.y=Math.max(.4,Math.min(4.5,result.position.y));const parent=this.el.object3D.parent,parentQ=parent.getWorldQuaternion(new T.Quaternion()).invert(),parentScale=parent.getWorldScale(new T.Vector3()),alpha=1-Math.exp(-Math.min(delta||16,60)/1000*20);const object=this.el.object3D;object.position.lerp(parent.worldToLocal(result.position),alpha);object.quaternion.slerp(parentQ.multiply(result.quaternion),alpha);object.scale.lerp(result.scale.divide(parentScale),alpha);this.suppressUntil=now+450},
 remove(){this.endMouseResize();this.releaseAll();this.el.sceneEl.removeEventListener('loaded',this.ready);this.listeners.forEach(fn=>fn());this.highlight.geometry.dispose();this.highlight.material.dispose();this.highlight.removeFromParent();this.resetButton?.remove()}
});
function setup(){const globe=document.getElementById('mapRoot');globe.setAttribute('bimanual-globe','');const reset=document.createElement('button');reset.type='button';reset.innerHTML='<span>↺</span>Reset globe';reset.style.display='none';reset.onclick=()=>globe.components['bimanual-globe']?.reset();document.getElementById('spatialDock').append(reset);const assign=()=>{const component=globe.components['bimanual-globe'];if(component){component.resetButton=reset;component.bindInputs()}};globe.addEventListener('componentinitialized',assign);assign();window.globiquest.resizeGlobe=delta=>globe.components['bimanual-globe']?.resizeTo(globe.object3D.scale.x+delta);window.globiquest.resetGlobeSize=()=>globe.components['bimanual-globe']?.resizeTo(1);window.globiquest.getGlobeScale=()=>globe.object3D.scale.x;window.globiquest.resetGlobe=()=>globe.components['bimanual-globe']?.reset();document.getElementById('help').innerHTML+='<br>Globe: pinch and hold to move; use both hands to resize and turn. Release to place.'}
if(scene.hasLoaded)setup();else scene.addEventListener('loaded',setup,{once:true});
})();
